sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    //STATUS MAPPING
    var status_obj = {
        "Open": "Reported",
        "Under Investigation": "Suspicious",
        "Awaiting Implementation": "Confirmed",
        "In Review": "Suspicious",
        "Resolved": "Remediated",
        "Deferred": "Not a Problem",

        "Closed": "Remediated",
        "Remediated - Auto-Verified": "Remediated",
        "Reported": "Reported"
    };

    var gri = new GlideRecordSecure('sn_sec_int_impl_config');
    gri.addEncodedQuery('implementation.name=Contrast Application Vulnerability^configuration=6fbf705c83295210b9b19b00feaad30e');
    gri.query();

    var grk = new GlideRecordSecure('sn_sec_int_impl_config');
    grk.addEncodedQuery('implementation.name=Contrast Application Vulnerability^configuration=3a1f705c83295210b9b19b00feaad360');
    grk.query();

    var status_val = status_obj[current.state.getDisplayValue()];
    //Trigger API
    try {
        var r = new sn_ws.RESTMessageV2('x_ntsi_contrast_ap.Contrast REST API', 'SAST OUTBOUND');
        var endpint = current.vulnerable_links + '/audit';


        if (gri.next() && grk.next()) {
            r.setRequestHeader('API-Key', grk.value);
            r.setRequestHeader('Authorization', gri.value);
			r.setRequestHeader('Content-Type', 'application/json');
            //			r.setQueryParameter('size','2000');
        }

        var obj = {
            "status": status_val,
            "comment": current.work_notes.getJournalEntry(1)
        };
        r.setEndpoint(endpint);
        r.setRequestBody(JSON.stringify(obj));
        var response = r.executeAsync();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();

        current.work_notes = httpStatus + ' - ' + responseBody;
        current.update();
    } catch (ex) {
        var message = ex.message;
    }

})(current, previous);
